{
  "name": "lll_send_scan_report",
  "confidence": "medium",
  "docstring": "Builds and sends an HCI BLE scan report event from the selected scan-set context, returning failure early if the scan set or PHY-state filter marks the report as invalid.",
  "subsystem": "ble",
  "var_renames": {
    "v4": "scan_ctx_base",
    "v5": "scan_ctx_id",
    "v6": "scan_ctx",
    "v10": "adv_ctx_id",
    "v11": "adv_ctx_base",
    "v19": "status",
    "v20": "evt_buf"
  },
  "struct_hints": [
    {
      "offset": 40,
      "meaning": "64-bit scan context timestamp base"
    },
    {
      "offset": 106,
      "meaning": "scan context state byte that must be zero before building the report"
    },
    {
      "offset": 107,
      "meaning": "scan context state byte copied into the report structure"
    },
    {
      "offset": 108,
      "meaning": "scan context validity/enabled byte required to be non-zero"
    },
    {
      "offset": 116,
      "meaning": "index of associated advertising/connection context used with adv_ctx_base"
    }
  ]
}
